                        "name": getattr(fc, "name", ""),
                        "args": dict(getattr(fc, "args", {}) or {}),
                        "result": None,
                    }
                    tool_history.append(entry)
                    if call_id:
                        _pending_calls[call_id] = entry
                fr = getattr(part, "function_response", None)
                if fr:
                    call_id = getattr(fr, "id", None) or getattr(fr, "name", "")
