                        raw_result = getattr(fr, "response", None)
                        if hasattr(raw_result, "model_dump"):
                            raw_result = raw_result.model_dump()
                        elif not isinstance(
                            raw_result,
                            (dict, list, str, int, float, bool, type(None)),
                        ):
